package main

import (
	"github.com/Elagoht/collage/pkg/collage"

	favicon "github.com/Elagoht/collage-favicon"
	highlight "github.com/Elagoht/collage-highlight"
	htmlcheck "github.com/Elagoht/collage-htmlcheck"
	i18n "github.com/Elagoht/collage-i18n"
	jsonld "github.com/Elagoht/collage-jsonld"
	meta "github.com/Elagoht/collage-meta"
	minimizer "github.com/Elagoht/collage-minimizer"
	robots "github.com/Elagoht/collage-robots"
	search "github.com/Elagoht/collage-search"
	sitemap "github.com/Elagoht/collage-sitemap"
	toc "github.com/Elagoht/collage-toc"
)

// plugins are the application's plugins, in order: the first is the outermost
// middleware. Their settings are in plugins-config.json; what has no JSON form —
// a filesystem — is given here.
//
// The minimizer is last, so it compacts what every plugin before it added to the
// page.
func plugins(devMode bool) []collage.Plugin {
	return []collage.Plugin{
		i18n.New(i18n.Options{FS: locales(devMode)}),
		meta.New(meta.Options{}),
		jsonld.New(jsonld.Options{}),
		sitemap.New(sitemap.Options{}),
		robots.New(robots.Options{}),
		favicon.New(favicon.Options{FS: embedded(devMode, staticFS)}),
		toc.New(toc.Options{}),
		highlight.New(highlight.Options{}),
		search.New(search.Options{}),
		htmlcheck.New(htmlcheck.Options{}),
		minimizer.New(minimizer.Options{}),
	}
}
